'use strict';
const $=id=>document.getElementById(id),icon=(name,cls='')=>`<svg class="ic ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EX=[
{name:'Flexão na parede',muscle:'Peito · tríceps · ombros',sets:[2,2,2,2],reps:['5–8','6–9','6–9','8–10'],steps:['Mãos na parede à altura do peito, ligeiramente mais abertas que os ombros.','Afasta os pés e mantém cabeça, tronco e pernas alinhados.','Dobra os cotovelos e aproxima o peito da parede; empurra para regressar. Expira ao empurrar.'],avoid:'Evita deixar a anca cair ou abrir demasiado os cotovelos.',note:'Se estiver muito fácil na semana 4, usa uma superfície ligeiramente mais baixa, fixa e resistente, e regressa a 5–8 repetições.'},
{name:'Remada com bidão',muscle:'Costas · bíceps · ombros posteriores',sets:[2,2,2,2],reps:['8','9–10','9–10','10–12'],steps:['Apoia a mão livre numa bancada firme. Inclina o tronco a partir das ancas, com costas alinhadas.','Com ambos os pés no chão e joelhos ligeiramente dobrados, deixa o braço com o bidão descer.','Puxa o cotovelo em direcção à anca sem rodar o tronco. Baixa devagar e repete do outro lado.'],avoid:'Não arredondes as costas nem puxes com um balanço do corpo.',note:'Começa com 1–2 litros de água, pega intacta e tampa firme. Uma série inclui ambos os braços.'},
{name:'Sentar e levantar',muscle:'Coxas · glúteos',sets:[1,1,2,2],reps:['6–8','8–10','6–8','8–10'],steps:['Encosta uma cadeira firme à parede. Pés apoiados à largura das ancas.','Inclina ligeiramente o tronco para a frente e levanta-te devagar; podes ajudar com as mãos.','Leva a anca para trás e volta a sentar com controlo. Usa apenas uma amplitude indolor.'],avoid:'Omite se provocar dor no joelho. Não deixes os joelhos cair para dentro.',note:'Não forces para cumprir a tabela. Um exercício omitido por dor fica registado como omitido.'},
{name:'Elevação lateral da perna',muscle:'Lateral da anca · glúteo médio',sets:[1,1,2,2],reps:['8','10','8','10'],steps:['Em pé, segura uma superfície firme e mantém o tronco direito.','Afasta ligeiramente uma perna para o lado, mantendo os dedos do pé voltados para a frente.','Regressa devagar, sem balançar nem inclinar o tronco. Completa ambos os lados.'],avoid:'Não levantes a perna muito alto. Omite se o apoio provocar dor no joelho.',note:'Uma série inclui ambos os lados. O destaque da imagem é indicativo da região muscular.'}
];
EX[0].sets.push(2,2,2,2,2,2,2,2);EX[0].reps.push('6–8','8–10','8–12','8–12','8–10','8–12','8–12','8–12');
EX[1].sets.push(2,2,2,2,2,3,3,3);EX[1].reps.push('8–10','10–12','10–12','10–12','8–10','8–10','10–12','10–12');
EX[2].sets.push(2,2,2,2,2,2,2,2);EX[2].reps.push('8–10','10–12','10–12','10–12','8–10','10–12','10–12','10–12');
EX[3].sets.push(2,2,2,2,2,2,2,2);EX[3].reps.push('10','10–12','10–12','10–12','10','10–12','12','12');
EX.push(
{name:'Flexão com apoio elevado',muscle:'Peito · tríceps · ombros',sets:[0,0,0,0,2,2,2,2,2,3,3,3],reps:['','','','','6–8','8–10','8–10','8–12','6–8','6–8','8–10','8–10'],steps:['Usa uma bancada fixa e resistente. Apoia as mãos um pouco mais abertas que os ombros. Quanto mais alto o apoio, mais fácil.','Recua os pés e mantém o corpo alinhado. Dobra os cotovelos e aproxima o peito do apoio, sem deixar cair a anca.','Empurra para regressar e expira. Se não controlares o movimento, continua na parede; não uses portas ou mesas que possam deslizar.'],avoid:'Não forces uma versão mais difícil só porque mudou o bloco. Mantém o apoio alto ou a parede se necessário.',note:'Ao mudares a inclinação, regressa à margem inferior de repetições. Não aumentes simultaneamente carga, séries e dificuldade.'},
{name:'Ponte de glúteos',muscle:'Glúteos · parte posterior das coxas',sets:[0,0,0,0,1,2,2,2,2,2,2,2],reps:['','','','','8','8','10','10–12','8–10','10–12','10–12','10–12'],steps:['Deita-te de costas num tapete, joelhos dobrados e pés apoiados à largura das ancas. Braços ao lado do tronco.','Contrai os glúteos e eleva a anca até alinhar ombros, ancas e joelhos, sem arquear a lombar.','Baixa devagar. Respira durante o movimento e usa apenas uma amplitude confortável.'],avoid:'Omite se provocar dor no joelho ou nas costas. Não empurres a anca para além do alinhamento.',note:'Movimento com peso corporal, sem carregar a anca com objectos.'},
{name:'Dead bug · controlo abdominal',muscle:'Abdómen · estabilização do tronco',sets:[0,0,0,0,0,0,0,0,1,2,2,2],reps:['','','','','','','','','5','5','6','6–8'],steps:['Deita-te de costas com braços para cima e ancas e joelhos dobrados aproximadamente a 90 graus. Mantém a lombar confortável e estável.','Baixa lentamente um braço e a perna oposta, apenas até onde consigas sem arquear as costas. Expira ao estender.','Regressa ao início e alterna o lado. Usa uma amplitude curta; podes começar por mover só uma perna.'],avoid:'Não prendas a respiração nem deixes a lombar arquear. Se provocar dor, omite.',note:'Repetições por lado. O objectivo é controlo, não velocidade nem amplitude máxima.'}
);
EX.forEach((e,i)=>{e.id=i;e.img=i;e.side=[1,3,6].includes(i);});
const BLOCKS=[{title:'Fundamentos',subtitle:'Retomar o movimento',weeks:'1–4',focus:'Técnica, rotina e adaptação',description:'Plano introdutório: quatro movimentos, caminhada leve e regresso progressivo.',start:0},{title:'Construção',subtitle:'Construir força',weeks:'5–8',focus:'Mais padrões de movimento',description:'Introduz flexão com apoio elevado e ponte de glúteos. Cinco exercícios por sessão, com doses ajustáveis.',start:4},{title:'Consolidação',subtitle:'Força e controlo',weeks:'9–12',focus:'Treinos A/B e estabilidade',description:'Alterna duas sessões de corpo inteiro e acrescenta controlo abdominal. Consolida antes de aumentar a dificuldade.',start:8}];
const blockOf=w=>Math.floor(w/4),weeksOf=b=>[b*4,b*4+1,b*4+2,b*4+3];
function exercisesFor(w,d=0){if(w<4)return [0,1,2,3];if(w<8)return [4,1,2,5,3];return d===2?[4,1,2,3,6]:[4,1,2,5,6];}
function strengthTitle(w,d){return w<8?'Força calisténica':d===2?'Treino B · controlo e estabilidade':'Treino A · força de base';}
const DAYS=[{name:'Segunda-feira',short:'SEG',type:'strength'},{name:'Terça-feira',short:'TER',type:'walk'},{name:'Quarta-feira',short:'QUA',type:'strength'},{name:'Quinta-feira',short:'QUI',type:'rest'},{name:'Sexta-feira',short:'SEX',type:'strength'},{name:'Sábado',short:'SÁB',type:'walk'},{name:'Domingo',short:'DOM',type:'rest'}];
const WALK=['10–15','12–15','15–20','20–25','20–25','20–25','25–30','25–30','25–30','25–30','30','30'],WEEKS=['Regressar com controlo','Construir consistência','Aumentar gradualmente','Consolidar a tua base','Introduzir novos movimentos','Estabilizar a execução','Consolidar a força','Rever a construção','Introduzir controlo abdominal','Aumentar com critério','Repetir com qualidade','Avaliar o percurso'],REQUIRED=[0,1,2,4,5];
const KEY='movimento-utilizador-v3';let storageOK=true,state={version:3,sessions:{},reviews:{},archives:[]},tab='home',selectedWeek=0,sessionDay=0,selectedBlock=0,timerID=null,timerEnd=0;
try{const raw=localStorage.getItem(KEY)||localStorage.getItem('movimento-utilizador-v2');if(raw){const parsed=JSON.parse(raw);if([2,3].includes(parsed?.version)&&parsed.sessions&&typeof parsed.sessions==='object'&&!Array.isArray(parsed.sessions))state={...parsed,version:3,reviews:parsed.reviews||{},archives:parsed.archives||[]};}}catch{storageOK=false;}
const key=(w,d)=>`${w}-${d}`,record=(w,d)=>state.sessions[key(w,d)]||{sets:{},skips:{},tasks:{}};
function editRecord(w,d){return state.sessions[key(w,d)]??={sets:{},skips:{},tasks:{}};}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageOK=false;toast('Não foi possível guardar. Exporta uma cópia do progresso no Perfil.');return false;}}
function done(w,d){return !!record(w,d).finished;}
function countWeek(w){return REQUIRED.filter(d=>done(w,d)).length;}
function blockCount(b){return weeksOf(b).reduce((n,w)=>n+countWeek(w),0);}
function blockAllowed(b){if(b===0)return true;return blockAllowed(b-1)&&blockCount(b-1)===20&&state.reviews[b-1]?.ready===true&&hasPhoto(b-1,'after');}
function activeBlock(){for(let b=0;b<3;b++)if(!blockAllowed(b+1)||b===2)return b;return 2;}
function focusWeek(){const b=activeBlock();for(const w of weeksOf(b))if(countWeek(w)<5)return w;return b*4+3;}

function nextDay(w){return REQUIRED.find(d=>!done(w,d))??null;}
function totalDone(){return Array.from({length:12},(_,w)=>countWeek(w)).reduce((n,v)=>n+v,0);}

function totalSets(){let n=0;for(let w=0;w<12;w++)for(const d of [0,2,4]){const r=record(w,d);exercisesFor(w,d).forEach(i=>{for(let j=0;j<EX[i].sets[w];j++)if(r.sets?.[`${i}-${j}`])n++;});}return n;}

function typeLabel(type){return {strength:'Força calisténica',walk:'Resistência leve',rest:'Recuperação'}[type];}
function typeIcon(type){return {strength:'fire',walk:'walk',rest:'leaf'}[type];}
function dose(e,w){return `${e.sets[w]} ${e.sets[w]===1?'série':'séries'} × ${e.reps[w]} repetições${e.side?' por lado':''}`;}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('toast').classList.remove('show'),4000);}
function navigate(view,w,d){if(Number.isInteger(w)){if(view==='photos'||view==='review')selectedBlock=w;else selectedWeek=w;}if(Number.isInteger(d))sessionDay=d;tab=view;const hash=view==='session'?`#session/${selectedWeek}/${sessionDay}`:view==='plan'?`#plan/${selectedWeek}`:['photos','review'].includes(view)?`#${view}/${selectedBlock}`:`#${view}`;if(location.hash!==hash)location.hash=hash;render();window.scrollTo({top:0,behavior:'instant'});}

function parseRoute(){const parts=location.hash.slice(1).split('/');tab=['home','plan','session','progress','profile','photos','review'].includes(parts[0])?parts[0]:'home';if(['photos','review'].includes(tab)){if(/^[0-2]$/.test(parts[1]||''))selectedBlock=+parts[1];}else if(/^(?:[0-9]|1[01])$/.test(parts[1]||''))selectedWeek=+parts[1];if(/^[0-6]$/.test(parts[2]||''))sessionDay=+parts[2];render();}

window.addEventListener('hashchange',()=>{parseRoute();window.scrollTo({top:0,behavior:'instant'});});
function navHTML(){return [['home','home','Início'],['plan','plan','Plano'],['progress','chart','Progresso'],['profile','user','Perfil']].map(([view,ic,label])=>`<a class="nav-item ${(['session','review'].includes(tab)?'plan':tab==='photos'?'progress':tab)===view?'active':''}" ${((['session','review'].includes(tab)?'plan':tab==='photos'?'progress':tab)===view)?'aria-current="page"':''} href="#${view==='plan'?`plan/${focusWeek()}`:view}">${icon(ic)}<span>${label}</span></a>`).join('');}
function heading(title,sub,badge=''){return `<div class="page-heading"><div><div class="eyebrow">PLANO PESSOAL · GERMANO</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${badge?`<span class="badge">${badge}</span>`:''}</div>`;}
function progressBar(n,max){return `<div class="progress-track" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${max}" aria-label="Sessões concluídas"><div class="progress-fill" style="width:${Math.round(n/max*100)}%"></div></div>`;}
function weekStrip(w){const next=nextDay(w);return `<div class="week-strip">${DAYS.map((d,i)=>`<button class="day-tile ${done(w,i)?'done':i===next?'focus':''}" data-session="${w},${i}" aria-label="Semana ${w+1}, ${d.name}, ${typeLabel(d.type)}, ${done(w,i)?'registado':'por fazer'}"><span class="label">${d.short}</span>${icon(done(w,i)?'check':typeIcon(d.type))}<span class="kind">${d.type==='strength'?'Força':d.type==='walk'?'Caminhada':'Descanso'}</span><span class="tiny-status">${done(w,i)?'Registado':i===next?'Próxima sessão':'Ao teu ritmo'}</span></button>`).join('')}</div>`;}
function library(w=focusWeek()){const indices=[...new Set([...exercisesFor(w,0),...exercisesFor(w,2)])];return `<div class="section-head"><h2>Conhece os movimentos</h2><span class="eyebrow">TÉCNICA PRIMEIRO</span></div><div class="mini-exercises">${indices.map(i=>`<button class="mini-ex" data-detail="${i}"><img src="assets/exercise-${i}.jpg" loading="lazy" alt="${EX[i].name}: posições inicial e final"><div><b>${EX[i].name}</b><small>Ver execução ${icon('arrow')}</small></div></button>`).join('')}</div>`;}

function home(){const w=focusWeek(),b=blockOf(w),d=nextDay(w),blockFinished=blockCount(b)===20,allFinished=b===2&&blockFinished,t=d!==null?DAYS[d].type:'strength';const beforeMissing=!hasPhoto(b,'before');return heading('Vamos a mais uma, atleta.','Um percurso de 12 semanas, dividido em três planos.',`Bloco ${b+1} · ${BLOCKS[b].title}`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">${blockFinished?'BLOCO '+(b+1)+' · FECHO E AVALIAÇÃO':`SEMANA ${w+1} · ${d!==null?DAYS[d].name.toUpperCase():''}`}</div><h2>${blockFinished?'Regista. Compara. Decide.':beforeMissing?'O teu ponto de partida merece um registo.':t==='walk'?'Recupera o teu ritmo.':'Mais força, uma série de cada vez.'}</h2><p>${blockFinished?'Adiciona a foto de depois e avalia a tua recuperação antes da fase seguinte.':beforeMissing?'Adiciona a foto de antes deste bloco. Ela fica privada neste navegador.':`${WEEKS[w]}. ${t==='walk'?'Caminhada confortável, sem dor.':exercisesFor(w,d).length+' movimentos. Controlo e consistência.'}`}</p><div class="hero-meta"><span>${icon('time')}${t==='walk'?WALK[w]+' min':w<4?'20–30 min estimados':'25–40 min estimados'}</span><span>${icon(typeIcon(t))}${BLOCKS[b].focus}</span></div>${blockFinished?`<button class="btn lime" data-review="${b}">${allFinished?'Avaliar o percurso':'Fechar bloco e avaliar'} ${icon('arrow')}</button>`:beforeMissing?`<button class="btn lime" data-photos="${b}">Adicionar foto de antes ${icon('arrow')}</button>`:`<button class="btn lime" data-session="${w},${d}">${(Object.values(record(w,d).sets||{}).some(Boolean)||Object.values(record(w,d).tasks||{}).some(Boolean))?'Continuar treino':'Abrir próxima sessão'} ${icon('arrow')}</button>`}</div><div class="hero-photo"><img src="assets/exercise-1.jpg" alt="Remada com apoio e músculos das costas destacados"></div></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('plan')}</span><div><b>${w+1}<span class="muted" style="font-size:12px"> / 12</span></b><small>Semana em foco</small></div></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><b>${blockCount(b)}<span class="muted" style="font-size:12px"> / 20</span></b><small>Sessões deste bloco</small></div></div><div class="stat"><span class="stat-icon">${icon('chart')}</span><div><b>${totalDone()}<span class="muted" style="font-size:12px"> / 60</span></b><small>Sessões do percurso</small></div></div></div>${blockCards(b)}<div class="section-head"><h2>A tua semana ${w+1}</h2><button class="btn ghost" data-plan="${w}">Ver plano ${icon('arrow')}</button></div>${weekStrip(w)}<div class="section-head"><h2>O registo também faz parte</h2><button class="btn ghost" data-photos="${b}">Fotos do bloco ${icon('arrow')}</button></div><div class="two-col"><section class="panel"><div class="panel-title"><h3>Uma semana de cada vez</h3><small>${countWeek(w)} / 5 sessões</small></div><p>Três treinos de força e duas caminhadas.</p>${progressBar(countWeek(w),5)}<div class="progress-caption"><span>Semana ${w+1}</span><span>${5-countWeek(w)} por registar</span></div></section><section class="panel"><div class="panel-title"><h3>Antes e depois · bloco ${b+1}</h3>${icon('chart')}</div><p class="helper">Antes: ${hasPhoto(b,'before')?'registado':'por adicionar'} · Depois: ${hasPhoto(b,'after')?'registado':blockFinished?'por adicionar':'no fim do bloco'}. As fotos são uma comparação visual, não uma medição de massa muscular.</p></section></div>${library()}`;}

function blockCards(current=blockOf(selectedWeek)){return `<div class="section-head"><h2>O teu percurso</h2><span class="eyebrow">3 PLANOS · 4 SEMANAS CADA</span></div><div class="block-cards">${BLOCKS.map((b,i)=>`<button class="block-card ${i===current?'current':''}" data-plan="${b.start}"><span class="block-number">0${i+1}</span><span class="status-chip">${blockAllowed(i)?blockCount(i)===20?'Sessões registadas':'Disponível':'Fase seguinte'}</span><h3>${b.title}</h3><p>${b.subtitle}</p><small>Semanas ${b.weeks} · ${blockCount(i)} / 20 sessões</small>${progressBar(blockCount(i),20)}</button>`).join('')}</div>`;}
function weekTabs(){const b=blockOf(selectedWeek);return `<div class="week-tabs" role="group" aria-label="Seleccionar semana">${weeksOf(b).map(w=>`<button class="week-tab ${selectedWeek===w?'active':''}" data-plan="${w}" aria-pressed="${selectedWeek===w}">Semana ${w+1} ${countWeek(w)===5?icon('check'):''}</button>`).join('')}</div>`;}

function plan(){const w=selectedWeek,b=blockOf(w),locked=!blockAllowed(b),next=nextDay(w)??0;return heading('Escolhe a semana. Abre o treino.','1. Plano → 2. Semana → 3. Dia de treino')+planBlockPicker(b)+`<div class="section-head"><h2>${BLOCKS[b].title} · semanas ${BLOCKS[b].weeks}</h2><button class="btn ghost" data-photos="${b}">Fotos e comparação ${icon('arrow')}</button></div><p>${BLOCKS[b].description}</p>`+weekTabs()+`${locked?`<div class="note">Podes consultar este plano. Para o iniciar, termina as sessões do bloco anterior, regista o antes/depois e faz a avaliação de transição. A passagem não é uma autorização médica.</div>`:''}<section class="panel" style="margin-bottom:20px"><div class="panel-title"><h2>${WEEKS[w]}</h2><span class="badge">${countWeek(w)} / 5 sessões</span></div><p>${w<4?['Movimentos controlados e esforço leve.','Aumenta apenas as repetições que conseguires controlar.','Acrescenta volume nas pernas apenas sem dor e com boa recuperação.','Consolida a técnica; muda uma variável de cada vez.'][w]:w%4===0?'Introduz os movimentos novos pela margem inferior das repetições; mantém uma versão mais fácil se necessário.':w%4===3?'Semana de consolidação e registo de resultados. Não é um teste máximo.':'Aumenta apenas se as duas sessões anteriores foram confortáveis, com boa técnica e recuperação.'}</p>${progressBar(countWeek(w),5)}<button class="btn primary full start-training" data-session="${w},${next}">${icon('arrow')} ${locked?'Ver como desbloquear':!hasPhoto(b,'before')?'Adicionar foto e iniciar':countWeek(w)===5?'Rever treino':'Abrir treino'} · ${DAYS[next].name}</button></section><div class="section-head"><h2>Treinos da semana ${w+1}</h2><small>Toca num dia para ver os exercícios</small></div><div class="plan-list">${DAYS.map((d,i)=>{const r=record(w,i),started=Object.values(r.sets||{}).some(Boolean)||Object.values(r.tasks||{}).some(Boolean);return `<button class="plan-day ${done(w,i)?'complete':''}" data-session="${w},${i}"><span class="day-icon">${icon(done(w,i)?'check':typeIcon(d.type))}</span><span class="day-info"><span class="eyebrow">${d.name}</span><strong>${d.type==='strength'?strengthTitle(w,i):typeLabel(d.type)}</strong><small>${d.type==='strength'?exercisesFor(w,i).length+' exercícios · '+(w<4?'20–30':'25–40')+' min estimados':d.type==='walk'?WALK[w]+' min · ritmo confortável':'Descanso e recuperação'}</small></span><span class="status-chip ${done(w,i)?'done':''}">${done(w,i)?'Ver registo':locked?'Fase seguinte':!hasPhoto(b,'before')?'Primeiro, a foto':d.type==='rest'?'Ver descanso':'Abrir treino'}</span>${icon('arrow','arrow')}</button>`;}).join('')}</div><div class="note">As semanas avançam pelas cinco sessões registadas. Entre blocos, há fotos e avaliação. Se não estiveres recuperado, repete sessões ou mantém a fase; não precisas de subir a dificuldade para cumprir o calendário.</div><button class="btn full" data-review="${b}" style="margin-top:15px">Avaliação do bloco ${b+1} ${icon('arrow')}</button><details class="safety"><summary>Tabela das quatro semanas deste bloco</summary><div class="table-wrap"><table><thead><tr><th>Exercício</th>${weeksOf(b).map(n=>`<th>Semana ${n+1}</th>`).join('')}</tr></thead><tbody>${[...new Set([...exercisesFor(w,0),...exercisesFor(w,2)])].map(i=>`<tr><th>${EX[i].name}</th>${weeksOf(b).map(n=>`<td>${EX[i].sets[n]} × ${EX[i].reps[n]}${EX[i].side?' / lado':''}</td>`).join('')}</tr>`).join('')}<tr><th>Caminhada</th>${weeksOf(b).map(n=>`<td>${WALK[n]} min</td>`).join('')}</tr></tbody></table></div></details>`;}

function safety(){return `<details class="safety"><summary>Cuidados gerais para treinar</summary><ul><li>Adapta os exercícios à tua capacidade e procura orientação profissional quando necessário.</li><li>Interrompe qualquer movimento que provoque dor ou mal-estar.</li><li>Descansa entre sessões e aumenta a dificuldade gradualmente.</li></ul></details>`;}

function checkProgress(w,d){const r=record(w,d);if(DAYS[d].type==='strength'){let total=1,completed=r.tasks?.warmup?1:0;exercisesFor(w,d).forEach(i=>{const e=EX[i];total+=e.sets[w];for(let j=0;j<e.sets[w];j++)if(r.sets?.[`${i}-${j}`]||r.skips?.[i])completed++;});return {total,completed,ready:completed===total};}if(DAYS[d].type==='walk'){const total=3,completed=['warmup','walk','cooldown'].filter(k=>r.tasks?.[k]).length;return {total,completed,ready:completed===total};}return {total:1,completed:done(w,d)?1:0,ready:true};}
function taskButton(k,title,description,r){return `<button class="task-check ${r.tasks?.[k]?'checked':''}" data-task="${k}" aria-pressed="${!!r.tasks?.[k]}"><span class="check-box">${r.tasks?.[k]?icon('check'):''}</span><span><strong>${title}</strong><small>${description}</small></span></button>`;}
function exerciseRows(w,d){const r=record(w,d);return exercisesFor(w,d).map((i,index)=>{const e=EX[i],skip=r.skips?.[i];return `<article class="exercise-row ${skip?'skipped':''}"><div class="exercise-summary"><img class="exercise-thumb" src="assets/exercise-${i}.jpg" alt="${e.name}"><div class="exercise-meta"><h3>${index+1}. ${e.name}</h3><p>${e.muscle}</p><span class="dose">${dose(e,w)}</span></div><div class="set-buttons">${Array.from({length:e.sets[w]},(_,j)=>`<button class="set-check ${r.sets?.[`${i}-${j}`]?'checked':''}" data-set="${i}-${j}" aria-pressed="${!!r.sets?.[`${i}-${j}`]}" ${skip?'disabled':''}>${icon(r.sets?.[`${i}-${j}`]?'check':'plan')} Série ${j+1}</button>`).join('')}</div></div><div class="exercise-actions"><button class="btn" data-detail="${i}">${icon('book')} Como executar</button><button data-skip="${i}">${skip?'Retomar exercício':'Omitir por dor / desconforto'}</button></div>${skip?'<div class="execution-note" style="margin:0 15px 15px">Omitido por desconforto. Não conta como séries executadas; a sessão ficará registada com adaptações.</div>':''}</article>`;}).join('');}
function completionHTML(w,d){const r=record(w,d),b=blockOf(w);return `<div class="completion">${icon('check')}<h2>${DAYS[d].type==='rest'?'Recuperação registada.':'Sessão registada, atleta.'}</h2><p>${r.partial?'Sessão com adaptações. Revê o desconforto antes de progredir.':'Cada sessão consistente conta para construir a tua base.'}</p>${blockCount(b)===20?`<p>As 20 sessões do bloco ${b+1} estão registadas. Adiciona o depois e avalia como recuperaste.</p><button class="btn primary" data-review="${b}">Fechar e avaliar bloco ${icon('arrow')}</button>`:countWeek(w)===5?`<p>As cinco sessões desta semana estão registadas. A próxima semana aparece no Início.</p>`:''}<div class="export-actions"><button class="btn primary" data-nav="home">Voltar ao início ${icon('arrow')}</button><button class="btn ghost" data-reopen>Corrigir registo</button>${DAYS[d].type!=='rest'?'<button class="btn" data-repeat>Repetir esta sessão</button>':''}</div></div>`;}

function finishForm(w,d){const r=record(w,d),p=checkProgress(w,d);return `<section class="finish-panel"><h3>Fecha a tua sessão</h3><p>${p.ready?'Os passos estão registados. Como te sentiste?':DAYS[d].type==='walk'?'Marca os três passos da caminhada antes de registar.':'Marca as séries realizadas ou omite os exercícios que não pudeste executar.'}</p><label for="effort">Como foi o esforço?</label><select id="effort"><option value="">Seleccionar (opcional)</option>${['Leve','Moderado','Difícil'].map(v=>`<option ${r.effort===v?'selected':''}>${v}</option>`).join('')}</select><label for="session-note">Nota pessoal (opcional)</label><textarea id="session-note" maxlength="500" placeholder="Como reagiu o joelho? Houve desconforto?">${esc(r.note||'')}</textarea><button class="btn primary full" id="finish" ${p.ready?'':'disabled'}>${icon('check')} Registar sessão</button><small style="display:block;margin-top:10px">Podes corrigir o registo depois. Uma sessão omitida parcialmente fica identificada como adaptada.</small></section>`;}
function session(){const w=selectedWeek,d=sessionDay,type=DAYS[d].type,r=record(w,d),p=checkProgress(w,d);let out=`<button class="back" data-plan="${w}">${icon('back')} Voltar à semana ${w+1}</button>`+heading(type==='strength'?strengthTitle(w,d):typeLabel(type),`Bloco ${blockOf(w)+1} · Semana ${w+1} · ${DAYS[d].name}`,type==='strength'?exercisesFor(w,d).length+' exercícios':type==='walk'?WALK[w]+' min':'Recuperação');if(!blockAllowed(blockOf(w)))return out+lockedBlock(blockOf(w));if(!hasPhoto(blockOf(w),'before'))return out+photoGate(blockOf(w));if(done(w,d))return out+completionHTML(w,d)+`${r.note?`<section class="panel"><h3>A tua nota</h3><p>${esc(r.note)}</p></section>`:''}`+safety();if(type==='rest')return out+`<section class="walk-visual">${icon('leaf')}<div><strong>Recuperar.</strong><small>Hoje também faz parte do plano.</small></div></section><section class="panel" style="margin-top:20px"><h2>Dá espaço à recuperação</h2><ul class="text-list"><li>Descansa dos treinos de força.</li><li>Se for confortável, faz movimentos suaves ao longo do dia.</li><li>Mantém a alimentação e procura proteger o sono.</li><li>Não precisas de compensar sessões perdidas.</li></ul><button class="btn primary full" id="rest-done">Registar dia de recuperação ${icon('check')}</button></section>`+safety();out+=`<div class="session-banner">${icon(typeIcon(type))}<div style="flex:1"><strong>${p.completed} / ${p.total} passos registados</strong><p>${type==='strength'?'Marca cada série depois de a realizares.':'Caminha sem dor e num ritmo confortável.'}</p></div>${type==='strength'?`<button class="btn" data-timer="90">${icon('time')} Descanso · 90 s</button>`:''}</div>`;if(type==='strength'){out+=taskButton('warmup','Aquecimento · 3–5 minutos','Caminhada suave, se indolor, e movimentos leves dos ombros e cotovelos.',r)+exerciseRows(w,d);}else{out+=`<div class="walk-visual">${icon('walk')}<div><strong>${WALK[w]} min</strong><small>Ritmo confortável · sem dor</small></div></div>`+taskButton('warmup','Começar devagar','Primeiros minutos suaves; observa como te sentes.',r)+taskButton('walk','Caminhada realizada','Mantém um ritmo em que consigas conversar. Não forces o joelho.',r)+taskButton('cooldown','Terminar suavemente','Abranda, recupera a respiração e regista como te sentiste.',r);}return out+finishForm(w,d)+safety();}
function progress(){const progressBlock=blockOf(selectedWeek);const history=Object.entries(state.sessions).filter(([k,r])=>r.finished&&/^(?:[0-9]|1[01])-[0-6]$/.test(k)).sort((a,b)=>(b[1].finished||'').localeCompare(a[1].finished||''));return heading('A evolução fica registada.','Consistência, séries e notas reais. Sem resultados inventados.')+`<div class="stats"><div class="stat"><span class="stat-icon">${icon('check')}</span><div><b>${totalDone()}</b><small>Sessões de treino registadas</small></div></div><div class="stat"><span class="stat-icon">${icon('fire')}</span><div><b>${totalSets()}</b><small>Séries marcadas como feitas</small></div></div><div class="stat"><span class="stat-icon">${icon('plan')}</span><div><b>${Array.from({length:12},(_,w)=>w).filter(w=>countWeek(w)===5).length}</b><small>Semanas com 5 sessões</small></div></div></div><div class="section-head"><h2>Os teus três blocos</h2></div>${blockCards(progressBlock)}<div class="section-head"><h2>Semanas do bloco ${progressBlock+1}</h2><button class="btn ghost" data-photos="${progressBlock}">Antes / Depois ${icon('arrow')}</button></div><div class="chart-weeks">${weeksOf(progressBlock).map(w=>`<button class="week-progress" data-plan="${w}" style="text-align:left;color:inherit;cursor:pointer"><h3>Semana ${w+1}</h3><strong>${countWeek(w)}<span class="muted" style="font-size:13px"> / 5</span></strong>${progressBar(countWeek(w),5)}<small>${WEEKS[w]}</small></button>`).join('')}</div><div class="section-head"><h2>Histórico de sessões</h2></div><section class="panel">${history.length?history.map(([k,r])=>{const [w,d]=k.split('-').map(Number);let date='';try{date=new Date(r.finished).toLocaleDateString('pt-PT',{day:'numeric',month:'short'});}catch{}return `<div class="history-item"><div><strong>Semana ${w+1} · ${DAYS[d].name}</strong><small>${typeLabel(DAYS[d].type)}${r.partial?' · com adaptações':''}${r.effort?' · '+esc(r.effort):''}</small>${r.note?`<p>${esc(r.note)}</p>`:''}</div><button class="btn ghost" data-session="${w},${d}">${esc(date)} ${icon('arrow')}</button></div>`;}).join(''):`<div class="empty">${icon('chart')}<h3>O primeiro registo começa contigo.</h3><p>Ao fechares uma sessão, ela aparece aqui.</p><button class="btn primary" data-nav="home">Abrir próximo treino</button></div>`}</section>${state.archives.length?`<p class="helper">${state.archives.length} sessão(ões) anteriores conservadas ao repetir. Os totais acima referem-se à passagem actual; a cópia completa inclui o histórico anterior.</p>`:''}<p class="helper" style="margin-top:20px">Sessões com adaptações entram no registo de consistência, mas séries omitidas não contam como realizadas. Estes números não medem ganho muscular nem substituem uma avaliação física.</p>`;}
function profile(){return heading('O teu espaço pessoal.','Registos de treino e cópias de segurança.')+`<section class="panel"><h3>O progresso fica neste navegador</h3><p>Os dados introduzidos no aplicativo ficam no dispositivo. Exporta uma cópia para os conservar.</p><div class="export-actions"><button class="btn" id="export">Exportar registos e fotos</button><button class="btn" id="import">Restaurar cópia</button><input type="file" id="import-file" accept="application/json,.json" hidden></div></section>${safety()}<section class="panel" style="margin-top:20px"><div id="offline-panel"><h3>Uso sem internet</h3><p>A verificar a cópia offline deste dispositivo…</p></div></section>`;}

function canTrackSession(){return blockAllowed(blockOf(selectedWeek))&&hasPhoto(blockOf(selectedWeek),'before');}
function render(){const n=navHTML();$('desktop-nav').innerHTML=n;$('mobile-nav').innerHTML=n;$('app').innerHTML=(!storageOK?'<div class="storage-warning">O armazenamento está indisponível. As alterações podem perder-se; exporta uma cópia no Perfil.</div>':'')+({home,plan,session,progress,profile,photos,review}[tab]||home)();bind();if(tab==='session'&&!canTrackSession()){document.querySelectorAll('[data-set],[data-task],[data-skip],#finish,#rest-done,#effort,#session-note').forEach(e=>e.disabled=true);}document.title=`${{home:'Início',plan:'Plano',session:'Treino',progress:'Progresso',profile:'Perfil',photos:'Fotos',review:'Avaliação'}[tab]} · Movimento`;}
function openDetail(i){const e=EX[i];$('dialog-content').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">GUIA DO MOVIMENTO</div><h2>${e.name}</h2></div><button id="close-dialog" aria-label="Fechar">${icon('close')}</button></div><img class="dialog-image" src="assets/exercise-${i}.jpg" alt="${e.name}, posições inicial e final"><div class="pose-labels"><span>01 · INÍCIO</span><span>02 · FINAL</span></div><div class="dialog-body"><div class="muscle-label">Músculos principais: ${e.muscle}</div><h3>Como executar</h3><ol>${e.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="execution-note">${e.avoid}</div><p style="margin-top:14px">${e.note}</p><small>Ilustração educativa gerada por IA. Os destaques musculares são indicativos; segue as instruções e adapta o movimento à tua capacidade.</small></div>`;$('close-dialog').onclick=()=>$('exercise-dialog').close();$('exercise-dialog').showModal();}
$('exercise-dialog').addEventListener('click',e=>{if(e.target===$('exercise-dialog'))$('exercise-dialog').close();});
function mutate(action){const y=window.scrollY;action();save();render();window.scrollTo(0,y);}
function bind(){bindBlocks();document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>navigate(e.dataset.nav));document.querySelectorAll('[data-plan]').forEach(e=>e.onclick=()=>navigate('plan',+e.dataset.plan));document.querySelectorAll('[data-session]').forEach(e=>e.onclick=()=>{const [w,d]=e.dataset.session.split(',').map(Number);navigate('session',w,d);});document.querySelectorAll('[data-detail]').forEach(e=>e.onclick=()=>openDetail(+e.dataset.detail));document.querySelectorAll('[data-set]').forEach(e=>e.onclick=()=>mutate(()=>{const r=editRecord(selectedWeek,sessionDay);r.sets??={};r.sets[e.dataset.set]=!r.sets[e.dataset.set];}));document.querySelectorAll('[data-task]').forEach(e=>e.onclick=()=>mutate(()=>{const r=editRecord(selectedWeek,sessionDay);r.tasks??={};r.tasks[e.dataset.task]=!r.tasks[e.dataset.task];}));document.querySelectorAll('[data-skip]').forEach(e=>e.onclick=()=>mutate(()=>{const r=editRecord(selectedWeek,sessionDay),i=+e.dataset.skip;r.skips??={};r.skips[i]=!r.skips[i];if(r.skips[i]){r.sets??={};for(let j=0;j<EX[i].sets[selectedWeek];j++)r.sets[`${i}-${j}`]=false;}}));document.querySelectorAll('[data-timer]').forEach(e=>e.onclick=()=>startTimer(+e.dataset.timer));if($('session-note'))$('session-note').oninput=e=>{editRecord(selectedWeek,sessionDay).note=e.target.value;save();};if($('effort'))$('effort').onchange=e=>{editRecord(selectedWeek,sessionDay).effort=e.target.value;save();};if($('finish'))$('finish').onclick=()=>{if(!checkProgress(selectedWeek,sessionDay).ready)return;const r=editRecord(selectedWeek,sessionDay);r.finished=new Date().toISOString();r.partial=Object.values(r.skips||{}).some(Boolean);save();stopTimer();render();window.scrollTo(0,0);};if($('rest-done'))$('rest-done').onclick=()=>{editRecord(selectedWeek,sessionDay).finished=new Date().toISOString();save();render();};document.querySelectorAll('[data-reopen]').forEach(e=>e.onclick=()=>{delete editRecord(selectedWeek,sessionDay).finished;save();render();});if($('export'))$('export').onclick=exportProgress;if($('import'))$('import').onclick=()=>$('import-file').click();if($('import-file'))$('import-file').onchange=importProgress;}
function startTimer(seconds){clearInterval(timerID);timerEnd=Date.now()+seconds*1000;$('timer').hidden=false;$('timer').innerHTML=`<small>Descanso · retoma só quando estiveres recuperado</small><strong id="timer-value"></strong><button id="timer-add">+30 s</button><button id="timer-stop" aria-label="Fechar temporizador">Fechar</button>`;$('timer-add').onclick=()=>{timerEnd+=30000;tick();};$('timer-stop').onclick=stopTimer;tick();timerID=setInterval(tick,500);}
function tick(){const remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if(!$('timer-value'))return;$('timer-value').textContent=remaining?`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`:'Ao teu ritmo';if(!remaining)clearInterval(timerID);}
function stopTimer(){clearInterval(timerID);$('timer').hidden=true;}


// Photos remain in IndexedDB on this browser. No image is sent over the network.
let photoDB=null,photoReady=false,photoError=false,photoBusy=false;const photoEntries=new Map();
const photoId=(b,phase)=>`${b}-${phase}`;
function hasPhoto(b,phase){return photoEntries.has(photoId(b,phase));}
function openPhotoDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Sem armazenamento de imagens'));return;}const request=indexedDB.open('movimento-fotos',1);request.onupgradeneeded=()=>request.result.createObjectStore('photos',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('Armazenamento ocupado'));});}
function readPhotoRows(){return new Promise((resolve,reject)=>{const tx=photoDB.transaction('photos','readonly'),r=tx.objectStore('photos').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function writePhotoRows(rows,replace=false){return new Promise((resolve,reject)=>{const tx=photoDB.transaction('photos','readwrite'),store=tx.objectStore('photos');if(replace)store.clear();for(const row of rows)store.put(row);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Gravação interrompida'));});}
function cachePhoto(row){const old=photoEntries.get(row.id);if(old?.url)URL.revokeObjectURL(old.url);photoEntries.set(row.id,{...row,url:URL.createObjectURL(row.blob)});}
async function initialisePhotos(){parseRoute();try{photoDB=await openPhotoDB();for(const row of await readPhotoRows())if(row.blob instanceof Blob)cachePhoto(row);}catch{photoError=true;}photoReady=true;render();}
function planBlockPicker(b){return `<div class="plan-block-picker" role="group" aria-label="Escolher plano">${BLOCKS.map((v,i)=>`<button class="plan-block-option ${i===b?'selected':''}" data-plan="${i*4}" aria-pressed="${i===b}"><span>PLANO ${i+1}</span><strong>${v.title}</strong><small>Semanas ${v.weeks}</small></button>`).join('')}</div>`;}
function photoGate(b){return `<section class="start-photo-note"><div><strong>Primeiro a foto. Depois, o teu treino.</strong><p>Adiciona a foto de antes do bloco ${b+1} para abrir os exercícios e marcar as séries. Este é o teu ponto de partida para a comparação no fim do bloco.</p></div><button class="btn primary" data-photos="${b}">Adicionar foto de antes ${icon('arrow')}</button></section>`;}

function lockedBlock(b){return `<section class="start-photo-note"><div><strong>Pré-visualização do plano ${b+1}</strong><p>Este plano vem depois do bloco ${b}. Para abrir os exercícios, termina a etapa anterior com as sessões, fotos e avaliação.</p></div><button class="btn" data-review="${Math.max(0,b-1)}">Ver etapa anterior ${icon('arrow')}</button></section>`;}

function photoDate(row){try{return new Date(row.addedAt).toLocaleDateString('pt-PT',{day:'numeric',month:'long',year:'numeric'});}catch{return 'Data indisponível';}}
function photoCard(b,phase){const row=photoEntries.get(photoId(b,phase)),after=phase==='after',canUpload=photoReady&&!photoError&&!photoBusy&&(!after||blockCount(b)===20),m=state.measurements?.[b]?.[phase];return `<article class="photo-card"><div class="photo-card-head"><span class="eyebrow">${after?'02 · DEPOIS':'01 · ANTES'}</span><span class="badge">${row?'Registada':after?'No fim do bloco':'Ponto de partida'}</span></div>${row?`<button class="progress-photo-button" data-zoom-photo="${b},${phase}" aria-label="Ampliar foto de ${after?'depois':'antes'} do bloco ${b+1}"><img class="progress-photo" src="${row.url}" alt="Foto de ${after?'depois':'antes'} do bloco ${b+1}, adicionada em ${photoDate(row)}"></button>`:`<div class="photo-placeholder">${icon('user')}<strong>${after?'O registo da tua evolução':'O começo deste bloco'}</strong><p>${after?'Adiciona após registares as 20 sessões.':'Escolhe uma foto antes do primeiro treino.'}</p></div>`}<div class="photo-card-body">${row?`<p class="photo-date">Adicionada em ${photoDate(row)}</p>${row.lateBaseline?'<div class="note">Registo inicial adicionado depois de já existirem sessões. Não representa necessariamente o estado anterior ao treino.</div>':''}`:''}<button class="btn ${row?'':'primary'} full" data-upload="${b},${phase}" ${canUpload?'':'disabled'}>${photoBusy?'A guardar…':row?'Substituir foto':after?'Adicionar foto de depois':'Tirar / escolher foto de antes'}</button><input type="file" data-photo-input="${b},${phase}" accept="image/jpeg,image/png,image/webp" hidden><label class="measurement-label" for="weight-${phase}">Peso de referência · opcional (kg)</label><input class="measure-input" id="weight-${phase}" data-weight="${b},${phase}" type="number" inputmode="decimal" min="20" max="300" step="0.1" placeholder="Ex.: 50,2" value="${m??''}"><small>Valor medido por ti; não é calculado pela imagem.</small></div></article>`;}
function photos(){const b=selectedBlock;return `<button class="back" data-plan="${b*4}">${icon('back')} Voltar ao bloco ${b+1}</button>`+heading('O teu antes. O teu depois.',`Bloco ${b+1} · ${BLOCKS[b].title}`,'Só neste navegador')+`<div class="week-tabs" role="group" aria-label="Fotos por bloco">${BLOCKS.map((v,i)=>`<button class="week-tab ${i===b?'active':''}" data-photos="${i}">Bloco ${i+1} · ${v.title}</button>`).join('')}</div><div class="photo-guidance"><h3>Compara nas mesmas condições</h3><p>Usa roupa de treino semelhante, a mesma pose, distância, iluminação e ângulo. Usa uma foto que já reúna as vistas que pretendes comparar. O aplicativo não analisa o corpo nem mede músculo ou gordura.</p></div>${photoError?'<div class="note">Este navegador não permitiu guardar imagens. Não vamos fingir que a foto ficou guardada. Tenta um navegador com armazenamento disponível e conserva cópias das imagens.</div>':''}${!photoReady?'<p>A carregar as fotos deste navegador…</p>':''}<div class="photo-compare">${photoCard(b,'before')}${photoCard(b,'after')}</div><div class="photo-guidance"><h3>As tuas imagens ficam contigo</h3><p>São guardadas apenas neste navegador, não são enviadas para o servidor e não sincronizam automaticamente. A exportação no Perfil inclui os registos e as fotos. Se limpares os dados do navegador, podes perdê-las.</p></div>${hasPhoto(b,'before')&&!hasPhoto(b,'after')?`<button class="btn primary full" data-session="${weeksOf(b).find(w=>countWeek(w)<5)??b*4+3},${nextDay(weeksOf(b).find(w=>countWeek(w)<5)??b*4+3)??0}" style="margin-top:18px">Foto registada · abrir treino ${icon('arrow')}</button>`:''}${blockCount(b)===20?`<button class="btn primary full" data-review="${b}" style="margin-top:18px">Ir à avaliação do bloco ${icon('arrow')}</button>`:''}`;}
const REVIEW_QUESTIONS=[['technique','Nas duas últimas sessões, mantiveste boa técnica e terminaste com repetições ainda possíveis?'],['pain','Treinaste sem dor ou agravamento do joelho durante o treino ou no dia seguinte?'],['recovery','Conseguiste recuperar entre sessões, alimentar-te e descansar de forma suficiente?'],['symptoms','Estás sem sintomas fora do habitual e esclareceste com um profissional eventuais episódios recorrentes de palpitações?']];
function review(){const b=selectedBlock,r=state.reviews[b]||{},complete=blockCount(b)===20,both=hasPhoto(b,'before')&&hasPhoto(b,'after'),allowed=blockAllowed(b);return `<button class="back" data-plan="${b*4+3}">${icon('back')} Voltar ao bloco ${b+1}</button>`+heading('Fecha um bloco. Decide o próximo.',`Bloco ${b+1} · ${BLOCKS[b].title}`)+`<section class="panel"><h2>O que ficou registado</h2><div class="review-facts"><span>${icon(complete?'check':'plan')} ${blockCount(b)} / 20 sessões</span><span>${icon(hasPhoto(b,'before')?'check':'user')} Foto de antes</span><span>${icon(hasPhoto(b,'after')?'check':'user')} Foto de depois</span></div><button class="btn" data-photos="${b}">Abrir comparação antes / depois ${icon('arrow')}</button></section>${!allowed?lockedBlock(b):''}${!complete?'<div class="note">A avaliação final é guardada quando as 20 sessões deste bloco estiverem registadas. Podes consultar as perguntas desde já.</div>':''}${!both?'<div class="note">Falta o registo fotográfico de antes e/ou depois. As fotos não precisam de mostrar uma transformação: documentam o que aconteceu, mesmo que a mudança visual seja pequena.</div>':''}<form id="review-form" class="panel" style="margin-top:20px"><h2>Como respondeste ao treino?</h2><p>Esta auto-avaliação organiza a progressão; não é diagnóstico nem autorização médica.</p>${REVIEW_QUESTIONS.map(([id,q],index)=>`<div class="review-question"><label for="review-${id}">${index+1}. ${q}</label><select id="review-${id}" name="${id}" required><option value="">Escolher resposta</option><option value="yes" ${r.answers?.[id]==='yes'?'selected':''}>Sim</option><option value="no" ${r.answers?.[id]==='no'?'selected':''}>Não / ainda não</option></select></div>`).join('')}<label class="measurement-label" for="review-note">O que melhorou e o que precisa de ajuste?</label><textarea id="review-note" maxlength="800" placeholder="Ex.: técnica, força, alimentação, sono, resposta do joelho…">${esc(r.note||'')}</textarea><button class="btn primary full" style="margin-top:18px" ${complete&&both&&allowed?'':'disabled'} type="submit">Guardar avaliação ${icon('check')}</button></form>${r.savedAt?`<section class="completion"><h2>${r.ready?b<2?'Pronto para considerar a fase seguinte.':'Percurso registado. Agora, revê a evolução.':'Mantém a fase e ajusta o que falta.'}</h2><p>${r.ready?b<2?'A fase seguinte foi disponibilizada. Começa pela foto de antes desse novo bloco e pela margem inferior das repetições.':'Não há um aumento automático para treinos extremos. Usa os registos para definir a continuação.':'Não aumentes a dificuldade por obrigação. Podes repetir sessões do plano actual e rever esta avaliação. Dor persistente ou sintomas fora do habitual exigem avaliação profissional.'}</p>${r.ready&&b<2?`<button class="btn primary" data-photos="${b+1}">Iniciar bloco ${b+2} · foto de antes ${icon('arrow')}</button>`:`<button class="btn" data-plan="${b*4+3}">Rever / repetir sessões do bloco ${icon('arrow')}</button>`}</section>`:''}<div class="note">Base da progressão: técnica controlada, descanso entre sessões e aumento gradual de uma variável de cada vez. As doses futuras são propostas, ajustáveis à tua resposta e às condições de alimentação e recuperação. <a class="link" href="https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/strength-training/art-20046670" target="_blank" rel="noopener">Referência: Mayo Clinic</a>.</div>`;}
async function photoUpload(file,b,phase){if(!file||photoBusy)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){toast('Usa uma imagem JPG, PNG ou WebP com até 8 MB.');return;}if(phase==='after'&&blockCount(b)!==20){toast('Regista as 20 sessões antes da foto de depois.');return;}if(!photoDB){toast('O armazenamento de fotos não está disponível neste navegador.');return;}if(hasPhoto(b,phase)&&!window.confirm('Substituir esta foto? Guarda uma cópia antes se quiseres conservar a anterior.'))return;photoBusy=true;render();try{const bitmap=await createImageBitmap(file);bitmap.close();const row={id:photoId(b,phase),block:b,phase,blob:file,addedAt:new Date().toISOString(),lateBaseline:phase==='before'&&weeksOf(b).some(w=>REQUIRED.some(d=>done(w,d)||Object.values(record(w,d).sets||{}).some(Boolean)||Object.values(record(w,d).tasks||{}).some(Boolean)))};await writePhotoRows([row]);cachePhoto(row);if(phase==='after'&&state.reviews[b]){state.reviews[b].ready=false;save();}toast('Foto guardada neste navegador.');}catch{toast('Não foi possível guardar a foto. Verifica o formato e o espaço disponível.');}finally{photoBusy=false;render();}}
function bindBlocks(){document.querySelectorAll('[data-photos]').forEach(e=>e.onclick=()=>navigate('photos',+e.dataset.photos));document.querySelectorAll('[data-review]').forEach(e=>e.onclick=()=>navigate('review',+e.dataset.review));document.querySelectorAll('[data-upload]').forEach(e=>e.onclick=()=>document.querySelector(`[data-photo-input="${e.dataset.upload}"]`).click());document.querySelectorAll('[data-photo-input]').forEach(e=>e.onchange=()=>{const [b,phase]=e.dataset.photoInput.split(',');photoUpload(e.files[0],+b,phase);});document.querySelectorAll('[data-weight]').forEach(e=>e.onchange=()=>{const [b,phase]=e.dataset.weight.split(',');state.measurements??={};state.measurements[b]??={};if(e.value==='')delete state.measurements[b][phase];else{const v=+e.value;if(!Number.isFinite(v)||v<20||v>300){toast('Introduz um peso entre 20 e 300 kg, ou deixa em branco.');return;}state.measurements[b][phase]=v;}save();});document.querySelectorAll('[data-zoom-photo]').forEach(e=>e.onclick=()=>{const row=photoEntries.get(e.dataset.zoomPhoto.replace(',','-'));if(!row)return;$('dialog-content').innerHTML=`<div class="dialog-head"><h2>Bloco ${row.block+1} · ${row.phase==='before'?'Antes':'Depois'}</h2><button id="close-dialog" aria-label="Fechar">${icon('close')}</button></div><img src="${row.url}" style="width:100%;max-height:70vh;object-fit:contain" alt="Foto pessoal de evolução"><p style="padding:0 20px 15px">Adicionada em ${photoDate(row)}</p>`;$('close-dialog').onclick=()=>$('exercise-dialog').close();$('exercise-dialog').showModal();});document.querySelectorAll('[data-repeat]').forEach(e=>e.onclick=()=>{if(!window.confirm('Repetir esta sessão? O registo actual será conservado no histórico anterior e esta sessão voltará a ficar por fazer.'))return;const k=key(selectedWeek,sessionDay),r=record(selectedWeek,sessionDay);state.archives.push({week:selectedWeek,day:sessionDay,record:JSON.parse(JSON.stringify(r)),archivedAt:new Date().toISOString()});state.sessions[k]={sets:{},skips:{},tasks:{}};const b=blockOf(selectedWeek);if(state.reviews[b])state.reviews[b].ready=false;save();render();});if($('review-form'))$('review-form').onsubmit=e=>{e.preventDefault();const b=selectedBlock;if(blockCount(b)!==20||!hasPhoto(b,'before')||!hasPhoto(b,'after')||!blockAllowed(b))return;const answers=Object.fromEntries(REVIEW_QUESTIONS.map(([id])=>[id,$('review-'+id).value]));if(Object.values(answers).some(v=>!['yes','no'].includes(v)))return;state.reviews[b]={answers,note:$('review-note').value,savedAt:new Date().toISOString(),ready:Object.values(answers).every(v=>v==='yes')};save();render();window.scrollTo(0,0);};}
function blobDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});}
async function exportProgress(){try{toast('A preparar a cópia com as fotos…');const photos=[];for(const row of photoEntries.values()){const {url,blob,...meta}=row;photos.push({...meta,data:await blobDataURL(blob)});}const payload={...state,photos},blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='movimento-copia-completa.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Cópia preparada. Conserva o ficheiro num local privado.');}catch{toast('Não foi possível preparar a cópia. Tenta novamente.');}}
function validateBackup(data){if(![2,3].includes(data?.version)||!data.sessions||typeof data.sessions!=='object'||Array.isArray(data.sessions)||Object.keys(data.sessions).length>84)throw Error('Formato inválido');const clean={version:3,sessions:{},reviews:{},archives:[],measurements:{}};function cleanRecord(r,w){const c={sets:{},skips:{},tasks:{}};for(let i=0;i<EX.length;i++){if(r.skips?.[i]===true)c.skips[i]=true;for(let j=0;j<EX[i].sets[w];j++)if(r.sets?.[`${i}-${j}`]===true)c.sets[`${i}-${j}`]=true;}for(const task of ['warmup','walk','cooldown'])if(r.tasks?.[task]===true)c.tasks[task]=true;if(typeof r.note==='string')c.note=r.note.slice(0,800);if(['Leve','Moderado','Difícil'].includes(r.effort))c.effort=r.effort;if(typeof r.finished==='string'&&!Number.isNaN(Date.parse(r.finished)))c.finished=r.finished;c.partial=Object.values(c.skips).some(Boolean);return c;}for(const [k,r]of Object.entries(data.sessions)){if(!/^(?:[0-9]|1[01])-[0-6]$/.test(k)||!r||typeof r!=='object')throw Error('Registo inválido');clean.sessions[k]=cleanRecord(r,+k.split('-')[0]);}for(let b=0;b<3;b++){const r=data.reviews?.[b];if(r&&typeof r==='object'){const answers=Object.fromEntries(REVIEW_QUESTIONS.map(([id])=>[id,r.answers?.[id]==='yes'?'yes':'no']));clean.reviews[b]={answers,note:typeof r.note==='string'?r.note.slice(0,800):'',savedAt:typeof r.savedAt==='string'?r.savedAt:'',ready:Object.values(answers).every(v=>v==='yes')};}for(const phase of ['before','after']){const v=data.measurements?.[b]?.[phase];if(typeof v==='number'&&v>=20&&v<=300){clean.measurements[b]??={};clean.measurements[b][phase]=v;}}}if(Array.isArray(data.archives))for(const a of data.archives.slice(-300)){if(Number.isInteger(a.week)&&a.week>=0&&a.week<12&&Number.isInteger(a.day)&&a.day>=0&&a.day<7&&a.record&&typeof a.record==='object')clean.archives.push({week:a.week,day:a.day,record:cleanRecord(a.record,a.week),archivedAt:typeof a.archivedAt==='string'?a.archivedAt:''});}return clean;}
async function decodeBackupPhotos(rows){if(rows===undefined)return null;if(!Array.isArray(rows)||rows.length>6)throw Error('Fotos inválidas');const result=[],seen=new Set();for(const r of rows){if(!r||!Number.isInteger(r.block)||r.block<0||r.block>2||!['before','after'].includes(r.phase)||typeof r.data!=='string')throw Error('Foto inválida');const m=r.data.match(/^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)$/);if(!m||m[2].length>12*1024*1024)throw Error('Formato de foto inválido');const bytes=Uint8Array.from(atob(m[2]),c=>c.charCodeAt(0));if(bytes.length>8*1024*1024)throw Error('Foto demasiado grande');const blob=new Blob([bytes],{type:m[1]}),bitmap=await createImageBitmap(blob);bitmap.close();const id=photoId(r.block,r.phase);if(seen.has(id))throw Error('Foto duplicada');seen.add(id);result.push({id,block:r.block,phase:r.phase,blob,addedAt:typeof r.addedAt==='string'&&!Number.isNaN(Date.parse(r.addedAt))?r.addedAt:new Date().toISOString(),lateBaseline:r.lateBaseline===true});}return result;}
async function importProgress(e){const file=e.target.files[0];if(!file)return;if(file.size>75*1024*1024){toast('A cópia é demasiado grande. Usa um ficheiro exportado pelo Movimento.');return;}try{const data=JSON.parse(await file.text()),imported=validateBackup(data),rows=await decodeBackupPhotos(data.photos);if(rows&&!photoDB)throw Error('Armazenamento de fotos indisponível');if(!window.confirm('Restaurar esta cópia substitui os registos deste navegador e, se a cópia as incluir, as fotos actuais. Queres continuar?'))return;if(rows){await writePhotoRows(rows,true);for(const r of photoEntries.values())URL.revokeObjectURL(r.url);photoEntries.clear();for(const r of rows)cachePhoto(r);}state=imported;save();render();toast('Cópia restaurada, incluindo as fotos disponíveis.');}catch{toast('Não foi possível restaurar. Usa uma cópia válida e verifica o espaço disponível.');}}
initialisePhotos();
